additionalInfo += sstr_(Strings_lenientFormat("
Either use a non-destructuring require or rewrite the goog.module "%s" to support destructuring requires. For example, consider replacing
  exports = {%s: <value>[, ...]};
with individual named export assignments like
  exports.%s = <value>;
", strobj_(importRecord.moduleRequest()), strobj_(importRecord.importName()), strobj_(importRecord.importName())))

